SELECT JSON_OBJECT('section','policies','id',CAST(a.`id` AS CHAR),'tenant',CAST(a.`tenant_id` AS CHAR),'domain',a.`data_domain`,'system',a.`system_code`,'objectType',a.`object_type`,'action',a.`action_code`,'state',a.`object_state`,'mode',a.`policy_mode`,'processKey',a.`process_definition_key`,'executor',a.`effect_executor_code`,'formPolicyType',a.`form_policy_type`,'formSlots',a.`form_slots_json`,'status',a.`status`,'deleted',(a.`deleted`+0)) FROM bpm_business_approval_policy a WHERE a.tenant_id IN ('1','122') AND a.data_domain='DCC' AND a.system_code='DCC' AND a.object_type='CONTROLLED_FILE' AND a.action_code IN ('UPLOAD','PUBLISH','OBSOLETE') ORDER BY a.`id`;

SELECT JSON_OBJECT('section','count','name','policies','count',COUNT(*)) FROM bpm_business_approval_policy a WHERE a.tenant_id IN ('1','122') AND a.data_domain='DCC' AND a.system_code='DCC' AND a.object_type='CONTROLLED_FILE' AND a.action_code IN ('UPLOAD','PUBLISH','OBSOLETE');

SELECT JSON_OBJECT('section','templates','id',CAST(n.`id` AS CHAR),'code',n.`code`,'name',n.`name`,'nickname',n.`nickname`,'type',n.`type`,'status',n.`status`,'params',n.`params`,'deleted',(n.`deleted`+0),'contentHash',SHA2(n.content,256)) FROM system_notify_template n WHERE n.code='dcc_publication_released' OR n.id=6829 ORDER BY n.`id`;

SELECT JSON_OBJECT('section','count','name','templates','count',COUNT(*)) FROM system_notify_template n WHERE n.code='dcc_publication_released' OR n.id=6829;

SELECT JSON_OBJECT('section','tables','table',TABLE_NAME,'engine',ENGINE,'collation',TABLE_COLLATION) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('bpm_business_approval_policy','bpm_business_approval_request','dcc_publication_notification_delivery','dcc_publication_notification_audit') ORDER BY TABLE_NAME;

SELECT JSON_OBJECT('section','count','name','tables','count',COUNT(*)) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('bpm_business_approval_policy','bpm_business_approval_request','dcc_publication_notification_delivery','dcc_publication_notification_audit');

SELECT JSON_OBJECT('section','columns','table',TABLE_NAME,'column',COLUMN_NAME,'type',COLUMN_TYPE,'nullable',IS_NULLABLE,'default',COLUMN_DEFAULT,'collation',COLLATION_NAME,'generationExpression',NULLIF(GENERATION_EXPRESSION,''),'generatedKind',CASE WHEN EXTRA LIKE '%VIRTUAL GENERATED%' THEN 'VIRTUAL' WHEN EXTRA LIKE '%STORED GENERATED%' THEN 'STORED' ELSE NULL END) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('bpm_business_approval_policy','bpm_business_approval_request','dcc_publication_notification_delivery','dcc_publication_notification_audit') ORDER BY TABLE_NAME,ORDINAL_POSITION;

SELECT JSON_OBJECT('section','count','name','columns','count',COUNT(*)) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('bpm_business_approval_policy','bpm_business_approval_request','dcc_publication_notification_delivery','dcc_publication_notification_audit');

SELECT JSON_OBJECT('section','indexes','table',TABLE_NAME,'index',INDEX_NAME,'sequence',SEQ_IN_INDEX,'column',COLUMN_NAME,'nonUnique',NON_UNIQUE,'subPart',SUB_PART,'indexType',INDEX_TYPE) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('bpm_business_approval_policy','bpm_business_approval_request','dcc_publication_notification_delivery','dcc_publication_notification_audit') ORDER BY TABLE_NAME,INDEX_NAME,SEQ_IN_INDEX;

SELECT JSON_OBJECT('section','count','name','indexes','count',COUNT(*)) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('bpm_business_approval_policy','bpm_business_approval_request','dcc_publication_notification_delivery','dcc_publication_notification_audit');

SELECT JSON_OBJECT('section','capture_end','database',DATABASE(),'serverUuid',@@server_uuid,'captureId',CAST(CONNECTION_ID() AS CHAR),'capturedAt',DATE_FORMAT(UTC_TIMESTAMP(6),'%Y-%m-%dT%H:%i:%s.%fZ'));
